mapper.insert:

    SELECT POST_APPLY_SEQ.NEXTVAL FROM DUAL

INSERT INTO POST_APPLY (
    APPLY_ID                /* 지원 아이디 */
  , POST_ID                 /* 게시글 아이디 */
  , USER_ID                 /* 사용자 아이디 */
  , RECRUIT_POSIT_TYPE_CD   /* 지원 포지션 코드 */
  , TECH_STACK_CD           /* 기술스택 (콤마 구분) */
  , APPLY_REASON            /* 지원 동기 */
  , PORTFOLIO_URL           /* 포트폴리오 URL */
  , STATUS_CD               /* 지원 상태 코드 (10: 대기) */
  , REG_DT                  /* 등록일 */
) VALUES (
    #{applyId}
  , #{postId}
  , #{userId}
  , #{recruitPositTypeCd}
  , #{techStackCdStr}
  , #{applyReason}
  , #{portfolioUrl}
  , #{statusCd}
  , SYSDATE
)

mapper.select:
SELECT COUNT(*)
FROM POST_APPLY
WHERE POST_ID = #{postId}
  AND USER_ID = #{userId}
